var g singleflight.Group

func GetUser(ctx context.Context, id string) (*User, error) {
    if u, ok := cache.Get(id); ok {
        return u, nil
    }
    v, err, _ := g.Do(id, func() (any, error) {
        u, err := db.LoadUser(ctx, id)
        if err != nil {
            return nil, err
        }
        ttl := 5*time.Minute + time.Duration(rand.Int63n(int64(time.Minute)))
        cache.Set(id, u, ttl)
        return u, nil
    })
    if err != nil {
        return nil, err
    }
    return v.(*User), nil
}
